export function getGemLegacyGuide(slug: string): GemLegacyGuide | null {
  return (GUIDES as Record<string, GemLegacyGuide>)[slug] ?? null;
}

export function isLegacyGemQualitySlug(slug: string): slug is LegacyGemQualitySlug {
  return LEGACY_GEM_QUALITY_SLUGS.includes(slug as LegacyGemQualitySlug);
}
